// -----------------------------------------------------------------------------
//  NAVIGATION
//
//  Two nav components with incompatible identity models. cmpSidebar identifies
//  by stable ID; cmpBottomNavigation identifies by 1-based POSITION in its own
//  Items table and has no ID field at all. Feeding one into the other selects
//  the wrong tab as soon as the two tables differ in length, which they do by
//  design: the sidebar carries six items plus a divider, the bottom bar four.
//
//  nfNavMobile is the mapping between them. It is the only place the two
//  identity models meet.
//
//  Icon names here are cmpBottomNavigation's OWN lowercase vocabulary
//  (home, search, bell, user, heart, settings, menu, folder, mail, calendar,
//  dashboard, analytics, plus, layers, file). They are NOT cmpSidebar's
//  TitleCase names and the two sets are not interchangeable. This component
//  has no Icons input, so the vocabulary cannot be extended per instance.
// -----------------------------------------------------------------------------

nfNavMobile = Table(
    { Idx: 1, ID: 1, Icon: "home",      Label: "Home" },
    { Idx: 2, ID: 2, Icon: "folder",    Label: "Tasks" },
    { Idx: 3, ID: 3, Icon: "file",      Label: "Requests" },
    { Idx: 4, ID: 4, Icon: "analytics", Label: "Reports" }
);

// Settings (5) and Help (6) are deliberately absent from the bottom bar and
// reachable only through the drawer. Four tabs keep the rhythm and the drawer
// already exists.


// -----------------------------------------------------------------------------
//  ROUTING
//  One routing table for the whole app. Both navs call this rather than each
//  carrying its own Switch, so a new screen is one line in one place.
//
//  This is a BEHAVIOUR user defined function: it takes a parameter and wraps
//  its body in braces, per house-rules s7. Named formulas cannot contain
//  Navigate; behaviour UDFs can. First use of the construct in this project,
//  so confirm it binds in Studio before relying on it elsewhere.
// -----------------------------------------------------------------------------

nfRoute(navID: Number): Void = {
    Switch(
        navID,
        1, Navigate(scrHome,   ScreenTransition.None),
        2, Navigate(scrMyTasks,     ScreenTransition.None),
        3, Navigate(scrAllRequests, ScreenTransition.None, { locMyRequestsOnly: false }),
        7, Navigate(scrAllRequests, ScreenTransition.None, { locMyRequestsOnly: true }),
        4, Navigate(scrReports,     ScreenTransition.None),
        5, Navigate(scrSettings,    ScreenTransition.None),
        6, Navigate(scrHelp,        ScreenTransition.None)
    )
};
